  // ── diatonic-vs-altered upper extensions (pedagogical spec §10.3). The
  // three upper slots are the NATURAL intervals above the root: 9th = R+2,
  // 11th = R+5, 13th = R+9. Each is read against the song's home-key scale:
  // in the scale = a safe added colour; outside it = snap to the nearest
  // scale tone, and THAT is the alteration the key actually wants (♭9/♯9/
  // ♯11/♭13) — standard secondary-dominant practice. The natural 11 over a
  // major 3rd is flagged separately as an avoid note (a semitone above the
  // 3rd clashes; jazz raises it to ♯11). Spec's stated frame, kept: tensions
  // are read off the PREVAILING key, not the chord's own secondary key, so a
  // secondary dominant's tensions read "altered" relative to home. Shown only
  // at L3 and only for chords that have a 7th.
export const EXT_SLOTS=[[2,"9"],[5,"11"],[9,"13"]];
  // An altered tension is spelled by its OWN accidental, not by the chart's
  // key spelling: a ♯11 printed "D♭" contradicts its own label. Diatonic
  // slots keep the key's spelling, since they belong to that scale.
export const spellAs=(pc,sharp)=>(sharp?SHARP:FLAT)[mod(pc,12)];
export function classifyExtensions(root,q){
    const scaleRoot = (S.keyMode==="minor")?mod(S.key+3,12):S.key;
    const scale=MAJOR_COLL[scaleRoot];
    const iv=CE_IV[q]||CE_IV[""];
    const majThird=iv.indexOf(4)>=0;
    return EXT_SLOTS.map(([semi,name])=>{
      const pc=mod(root+semi,12);
      if(name==="11" && majThird){
        return {name, kind:"avoid", label:"♯11", note:spellAs(mod(root+6,12),true),
                why:"the natural 11 sits a semitone above the 3rd — raise it to ♯11"};
      }
      if(scale.has(pc)) return {name, kind:"diatonic", label:name, note:note(pc),
                                why:"in the key — a safe added colour"};
      const dn=mod(pc-1,12), up=mod(pc+1,12);
      const to = scale.has(dn)?dn:(scale.has(up)?up:null);
      if(to===null) return {name, kind:"diatonic", label:name, note:note(pc), why:"outside the key"};
      const down = (to===dn);
      const label = name==="9" ? (down?"♭9":"♯9") : name==="11" ? "♯11" : (down?"♭13":"♯13");
      return {name, kind:"altered", label, note:spellAs(to,label.indexOf("♯")>=0),
              why:"borrowed to fit the key — the tension it actually wants here"};
    });
  }
export function buildExtensions(root,q){
    if(!sev4(q)) return null;
    const box=el("div","flex:0 0 auto;");
    box.appendChild(el("div",`font:600 9px ${UI};letter-spacing:.06em;text-transform:uppercase;color:${T.faint};margin:14px 0 8px;`,"Colours you can add"));
    const row=el("div","display:flex;gap:8px;");
    const COL={diatonic:T.green, altered:T.amber, avoid:T.faint};
    classifyExtensions(root,q).forEach(x=>{
      const c=el("div",`flex:1;min-width:0;background:${T.paper};border:1px solid ${T.line};border-left:3px solid ${COL[x.kind]};border-radius:9px;padding:7px 8px;`);
      const h=el("div","display:flex;align-items:baseline;gap:5px;");
      h.appendChild(el("span",`font:italic 700 15px ${SERIF};color:${T.ink};`,x.label));
      h.appendChild(el("span",`font:600 11px ${UI};color:${COL[x.kind]};`,x.note));
      c.appendChild(h);
      c.appendChild(el("div",`font:500 9.5px ${UI};color:${T.faint};margin-top:3px;line-height:1.3;`,x.why));
      row.appendChild(c);
    });
    box.appendChild(row);
    return box;
  }

  // ── chord sheet — "what does this chord look like" (handoff feature #2).
  // Tap a chord in Read/Analyse → bottom sheet: piano illustration with the
  // bass accented, then the level's alternate voicings side by side.
export function openChordSheet(idx){
    const ch=S.chords[idx]; if(!ch||ch.nc) return;
    const lv=learnLevel();
    const q=dispQ(ch.q);
    const bass=(lv>=3)?ch.bass:-1;
    const back=overlay(); const sheet=sheetCol(); sheet.appendChild(handle());
    const hd=el("div","flex:0 0 auto;display:flex;align-items:baseline;gap:10px;margin-bottom:10px;flex-wrap:wrap;");
    hd.appendChild(glyph(ch.root,q,26,"exact",T.ink,bass));
    const close=voClose(ch.root,q);
    const names=close.map(m=>note(mod(m,12))).join(" · ");
    const bassTxt=(bass!=null&&bass>=0&&mod(bass,12)!==mod(ch.root,12))?note(bass)+" in the bass":"root in the bass";
    hd.appendChild(el("span",`font:italic 12px ${SERIF};color:${T.faint};`,names+" — "+bassTxt));
    sheet.appendChild(hd);
    const kb=el("div","flex:0 0 auto;"); sheet.appendChild(kb);
    const capBox=el("div",`min-height:16px;font:italic 11.5px ${SERIF};color:${T.faint};margin-top:8px;`,"");
    sheet.appendChild(capBox);
    sheet.appendChild(el("div",`flex:0 0 auto;font:600 9px ${UI};letter-spacing:.06em;text-transform:uppercase;color:${T.faint};margin:12px 0 8px;`,"A few ways to play it"));
    const strip=el("div","flex:0 0 auto;display:flex;gap:8px;");
    const cards=voicingCards(ch.root,q,lv,bass);
    let selCard=null;
    function show(card){
      selCard=card;
      const m=card.rootless?card.midis:withBass(card.midis,ch.root,bass);
      renderVoicing(kb,m,92,true);
      capBox.textContent=card.rootless?"Root omitted — a bassist plays it; the lowest note here is the 3rd or 7th.":"";
      [...strip.children].forEach(c=>{ c.style.outline=(c._card===card)?`2.5px solid ${T.accent}`:""; c.style.outlineOffset=(c._card===card)?"1px":""; });
      playMidis(m); haptic(6);
    }
    cards.forEach(card=>{
      const c=el("button",`flex:1;min-width:0;background:${T.paper};border:1px solid ${T.line};border-radius:10px;padding:8px 6px;text-align:center;cursor:pointer;`);
      c._card=card;
      c.appendChild(el("div",`font:700 11px ${UI};color:${T.ink};margin-bottom:6px;white-space:nowrap;`,card.label));
      const mp=el("div",""); c.appendChild(mp);
      renderVoicing(mp,card.rootless?card.midis:withBass(card.midis,ch.root,bass),34,false);
      c.onclick=()=>show(card);
      strip.appendChild(c);
    });
    sheet.appendChild(strip);
    if(lv>=3){ const ext=buildExtensions(ch.root,q); if(ext) sheet.appendChild(ext); }
    const closeBtn=el("button",`flex:0 0 auto;width:100%;margin-top:12px;background:transparent;border:none;color:${T.faint};font:600 13px ${UI};padding:8px;min-height:44px;cursor:pointer;`,"Close");
    closeBtn.onclick=()=>closeOverlay(back);
    sheet.appendChild(closeBtn);
    back.appendChild(sheet); root.appendChild(back);
    // draw + sound the default (close) voicing
    selCard=cards[0];
    const m0=selCard.rootless?selCard.midis:withBass(selCard.midis,ch.root,bass);
    renderVoicing(kb,m0,92,true);
    [...strip.children].forEach(c=>{ c.style.outline=(c._card===selCard)?`2.5px solid ${T.accent}`:""; c.style.outlineOffset=(c._card===selCard)?"1px":""; });
    kb.style.cursor="pointer";
    kb.onclick=()=>{ if(selCard) playMidis(selCard.rootless?selCard.midis:withBass(selCard.midis,ch.root,bass)); };
  }
  // Share sheet (UX audit 2026-07-20): a plain link (Web Share API, or copy
  // if unsupported) plus an iReal Pro export — the chord chart as an
  // irealb:// URL iReal Pro can open directly (see harmonia/irealb_export.py,
  // the reverse of the existing iReal IMPORT path). navigator.share()
  // validates its `url` as http(s), so the custom irealb:// scheme goes
  // through location assignment instead, with a clipboard fallback if
  // nothing was there to catch it.
export function openShareSheet(){
    if(!S.model || !S.model.file) return;
    const back=overlay(); const sheet=sheetBox(); sheet.appendChild(handle());
    sheet.appendChild(el("div",`text-align:center;font:700 15px ${UI};color:${T.ink};margin-bottom:2px;`,"Share this chart"));
    sheet.appendChild(el("div",`text-align:center;font:italic 12px ${SERIF};color:${T.faint};margin-bottom:16px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;`, S.model.title));

    const rows=el("div","display:flex;flex-direction:column;gap:10px;");
    const mkRow=(label,sub,onClick)=>{
      const b=el("button",`display:flex;align-items:center;justify-content:space-between;gap:10px;width:100%;border:1px solid ${T.line};background:${T.paper};border-radius:12px;padding:12px 14px;cursor:pointer;text-align:left;`);
      const tx=el("div","flex:1;min-width:0;");
      tx.appendChild(el("div",`font:600 13.5px ${UI};color:${T.ink};`,label));
      if(sub) tx.appendChild(el("div",`font:500 11.5px ${UI};color:${T.faint};margin-top:1px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;`,sub));
      b.appendChild(tx);
      b.appendChild(el("span",`flex:0 0 auto;font:400 18px ${UI};color:${T.rule};`,"›"));
      b.onclick=onClick;
      rows.appendChild(b);
    };

    const chartUrl=location.origin+"/?open="+encodeURIComponent(S.model.file);
    mkRow("Share link","Opens straight into this chart",async()=>{
      if(navigator.share){ try{ await navigator.share({title:S.model.title,url:chartUrl}); closeOverlay(back); return; }catch(e){ return; } }
      try{ await navigator.clipboard.writeText(chartUrl); toast("Link copied"); }catch(e){ toast("Could not copy"); }
      closeOverlay(back);
    });
    mkRow("Export to iReal Pro","Opens in the app if installed, else copies the link",async()=>{
      closeOverlay(back);
      try{
        const r=await api.get("/api/irealb-export/"+S.model.file);
        if(r.error){ toast("Could not export"); return; }
        window.location=r.url;
        setTimeout(()=>{ navigator.clipboard?.writeText(r.url).then(()=>toast("iReal Pro not found — link copied instead")).catch(()=>{}); },900);
      }catch(e){ toast("Could not export"); }
    });
    sheet.appendChild(rows);

    const cancel=el("button",`width:100%;margin-top:14px;border:none;background:transparent;color:${T.faint};font:600 13px ${UI};padding:8px;min-height:44px;cursor:pointer;`,"Cancel");
    cancel.onclick=()=>closeOverlay(back);
    sheet.appendChild(cancel);

    back.appendChild(sheet); root.appendChild(back);
  }
export function openRotor(){
    const back=overlay(); const sheet=sheetBox(); sheet.appendChild(handle());
    sheet.appendChild(el("div",`text-align:center;font:700 15px ${UI};color:${T.ink};margin-bottom:2px;`,"Change key"));
    sheet.appendChild(el("div",`text-align:center;font:italic 12px ${SERIF};color:${T.faint};margin-bottom:14px;`,"spin the circle of fifths — the whole chart transposes"));

    const size=250, R=size*0.40;
    const wheel=el("div",`position:relative;width:${size}px;height:${size}px;margin:0 auto;touch-action:none;cursor:grab;`);
    const ring=el("div","position:absolute;inset:0;transform-origin:50% 50%;will-change:transform;");
    wheel.appendChild(ring);
    const pointer=el("div",`position:absolute;top:-9px;left:50%;transform:translateX(-50%);width:0;height:0;border-left:8px solid transparent;border-right:8px solid transparent;border-top:13px solid ${T.accent};z-index:3;`);
    wheel.appendChild(pointer);
    // stops are circle-of-fifths ordered, so a notch = a fifth, not a semitone
    const stops=[]; for(let f=0;f<12;f++) stops.push(mod(f*7,12));
    const start=stops.indexOf(S.key);   // rotate so the current key sits under the pointer
    const btns=[];
    stops.forEach((pc,i)=>{
      const ang=(-90+i*30)*Math.PI/180;
      const b=el("button",`position:absolute;left:50%;top:50%;width:44px;height:44px;margin:-22px 0 0 -22px;border-radius:50%;border:none;background:${keyFill(pc)};color:#fff;font:italic 700 15px ${SERIF};cursor:pointer;box-shadow:0 2px 6px rgba(0,0,0,.2);transform:translate(${Math.cos(ang)*R}px, ${Math.sin(ang)*R}px);`);
      const lbl=el("span","display:block;pointer-events:none;",note(pc));
      b.appendChild(lbl); b._lbl=lbl; b._i=i; b._pc=pc;
      ring.appendChild(b); btns.push(b);
    });
    const hub=el("div",`position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:96px;height:96px;border-radius:50%;background:${T.card};border:1.5px solid ${T.line};display:flex;flex-direction:column;align-items:center;justify-content:center;pointer-events:none;z-index:2;`);
    const hubKey=el("div",`font:italic 700 26px ${SERIF};color:${T.ink};`,note(S.key));
    const hubMode=el("div",`font:500 11px ${UI};color:${T.faint};`, S.model?S.model.key.mode:"major");
    hub.appendChild(hubKey); hub.appendChild(hubMode); wheel.appendChild(hub);
    sheet.appendChild(wheel);

    let rot=-start*30, dragging=false, startAngle=0, startRot=0, moved=0, lastNotch=Math.round(rot/30);
    function detent(raw){
      const notch=Math.round(raw/30)*30, diff=raw-notch;
      const t=Math.max(-1,Math.min(1,diff/15));
      return notch + Math.sign(t)*Math.pow(Math.abs(t),1.7)*15;   // resist near the stop, give at the edge
    }
    function keyAt(deg){ return stops[mod(Math.round(-deg/30),12)]; }
    function applyRot(deg,animate){
      ring.style.transition = animate ? "transform .45s cubic-bezier(.32,1.5,.55,1)" : "none";
      const shown=animate?deg:detent(deg);
      ring.style.transform=`rotate(${shown}deg)`;
      btns.forEach(b=>{ b._lbl.style.transition=ring.style.transition; b._lbl.style.transform=`rotate(${-shown}deg)`; });
      const pc=keyAt(shown); hubKey.textContent=note(pc);
    }
    applyRot(rot,false);
    function feedback(){ playTick(); haptic(6); pointer.animate([{transform:"translateX(-50%) scale(1)"},{transform:"translateX(-50%) scale(1.35)"},{transform:"translateX(-50%) scale(1)"}],{duration:160}); }
    function angleAt(x,y){ const r=wheel.getBoundingClientRect(); return Math.atan2(y-(r.top+r.height/2), x-(r.left+r.width/2))*180/Math.PI; }
    wheel.addEventListener("pointerdown",e=>{
      dragging=true; moved=0; wheel.setPointerCapture(e.pointerId);
      startAngle=angleAt(e.clientX,e.clientY); startRot=rot; lastNotch=Math.round(rot/30);
      wheel.style.cursor="grabbing";
    });
    wheel.addEventListener("pointermove",e=>{
      if(!dragging) return;
      let d=angleAt(e.clientX,e.clientY)-startAngle;
      while(d>180) d-=360; while(d<-180) d+=360;
      moved=Math.max(moved,Math.abs(d));
      rot=startRot+d; applyRot(rot,false);
      const n=Math.round(rot/30);
      if(n!==lastNotch){ lastNotch=n; feedback(); }
    });
    function endDrag(e){
      if(!dragging) return;
      dragging=false; wheel.style.cursor="grab";
      const tapped = moved<8 ? (e.target.closest && e.target.closest("button")) : null;
      if(tapped){
        let target=-tapped._i*30;
        while(target-rot>180) target-=360;
        while(target-rot<-180) target+=360;
        rot=target;
      } else {
        rot=Math.round(rot/30)*30;
      }
      applyRot(rot,true); feedback();
      const pc=keyAt(rot);
      setTimeout(()=>{ transposeTo(pc); closeOverlay(back); }, 380);   // let the snap land first
    }
    wheel.addEventListener("pointerup",endDrag);
    wheel.addEventListener("pointercancel",endDrag);

    const cancel=el("button",`width:100%;margin-top:16px;background:transparent;border:none;color:${T.faint};font:600 13px ${UI};padding:8px;min-height:44px;cursor:pointer;`,"Cancel");
    cancel.onclick=()=>closeOverlay(back); sheet.appendChild(cancel);
    back.appendChild(sheet); root.appendChild(back);
  }
  // Display-only transposition: it rotates what you READ, it does not re-decode
  // the audio, so the playhead and any re-infer still address the real track.
export function transposeTo(pc){ const d=mod(pc-S.key,12); S.chords.forEach(c=>{ c.root=mod(c.root+d,12); if(c.sug) c.sug.forEach(s=>{ s.root=mod(s.root+d,12); }); }); S.key=pc; go("chart"); }

